"""
generate_labels_ts.py
Phase 1 utility — generates web/src/lib/labels.ts from the split label map.

Usage:
  python -m ml.scripts.generate_labels_ts
"""
from __future__ import annotations

import argparse
import json
from pathlib import Path


def main(label_map_path: str, out_path: str) -> None:
    label_map: dict[str, int] = json.loads(Path(label_map_path).read_text())
    # Sort by index to build ordered list
    ordered = sorted(label_map.items(), key=lambda kv: kv[1])
    labels_list = [gloss for gloss, _ in ordered]

    lines = [
        "/**",
        " * labels.ts — AUTO-GENERATED by ml/scripts/generate_labels_ts.py",
        " * Do not edit manually. Re-run the script after changing the label map.",
        " */",
        "",
        f"export const LABELS: string[] = {json.dumps(labels_list, indent=2)};",
        "",
        f"export const NUM_CLASSES = {len(labels_list)};",
        "",
    ]
    out = Path(out_path)
    out.parent.mkdir(parents=True, exist_ok=True)
    out.write_text("\n".join(lines))
    print(f"Generated {out} with {len(labels_list)} labels.")


if __name__ == "__main__":
    parser = argparse.ArgumentParser()
    parser.add_argument("--label-map", default="ml/data/splits/label_map.json")
    parser.add_argument("--out",       default="web/src/lib/labels.ts")
    args = parser.parse_args()
    main(args.label_map, args.out)
